'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var expf = require( '@stdlib/math/base/special/expf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var randu = require( '@stdlib/random/base/randu' );
var tryRequire = require( '@stdlib/utils/try-require' );
var EPS = require( '@stdlib/constants/float32/eps' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );


// FIXTURES //

var negative = require( './fixtures/python/negative.json' );
var positive = require( './fixtures/python/positive.json' );
var largePositive = require( './fixtures/python/large_positive.json' );


// VARIABLES //

var log1pexpf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( log1pexpf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof log1pexpf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN`, the function returns `NaN`', opts, function test( t ) {
	var v = log1pexpf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `-infinity`, the function returns `+0`', opts, function test( t ) {
	var v = log1pexpf( NINF );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `+infinity`, the function returns `+infinity`', opts, function test( t ) {
	var v = log1pexpf( PINF );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function computes the natural logarithm of `1+exp(x)` (`x <= -17.0`)', opts, function test( t ) {
	var x;
	var y;
	var v;
	var i;

	// NOTE: the native and JavaScript implementations of `expf` may differ by 1 ULP when the compiler contracts operations into fused multiply-add instructions.
	for ( i = 0; i < 1e3; i++ ) {
		v = f32( -17.0 - ( randu() * 100.0 ) );
		x = log1pexpf( v );
		y = expf( v );
		t.strictEqual( isAlmostSameValuef( x, y, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the natural logarithm of `1+exp(x)` (`x > 16.0`)', opts, function test( t ) {
	var x;
	var v;
	var i;

	for ( i = 0; i < 1e3; i++ ) {
		v = f32( 16.0 + EPS + ( randu() * 100.0 ) );
		x = log1pexpf( v );
		t.strictEqual( x, v, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural logarithm of `1+exp(x)` (negative values)', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = negative.x;
	expected = negative.expected;
	for ( i = 0; i < x.length; i++ ) {
		v = log1pexpf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural logarithm of `1+exp(x)` (positive values)', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = positive.x;
	expected = positive.expected;
	for ( i = 0; i < x.length; i++ ) {
		v = log1pexpf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural logarithm of `1+exp(x)` (large positive values)', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = largePositive.x;
	expected = largePositive.expected;
	for ( i = 0; i < x.length; i++ ) {
		v = log1pexpf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( v, e, 'returns expected value' );
	}
	t.end();
});
